svg.script:
(function() {
  var detailLines = [];
  var N_LINES = 8;
  var searchBtn;
  var defaultHint = "Hover a bar for details; click a bar to pin details  ·  Ctrl+F to search";
  var searching = false;
  var pinnedBar = null;

  function setDetailsText(parts) {
    for (var i = 0; i < N_LINES; i++) {
      if (!detailLines[i]) continue;
      detailLines[i].textContent = (i < parts.length) ? parts[i] : "";
      detailLines[i].setAttribute("class", "details-line" + (i > 0 && i >= parts.length - 1 && parts.length > 1 ? " dim" : ""));
    }
  }

  function clearDetails() {
    if (detailLines[0]) detailLines[0].textContent = defaultHint;
    for (var i = 1; i < N_LINES; i++) {
      if (detailLines[i]) { detailLines[i].textContent = ""; detailLines[i].setAttribute("class", "details-line"); }
    }
  }

  function setDetailsForBar(bar) {
    if (!bar || !detailLines[0]) return;
    var info = bar.getAttribute("data-info") || "";
    var analysisMsg = bar.getAttribute("data-analysis-msg");
    if (analysisMsg)
      info = info + "  ·  ⚠ In Query Analysis: " + analysisMsg;
    var sep = "  ·  ";
    var parts = info.split(sep);
    setDetailsText(parts);
  }

  function init(evt) {
    for (var i = 0; i < N_LINES; i++) {
      var el = document.getElementById("details-l" + i);
      if (el) detailLines.push(el);
    }
    searchBtn = document.getElementById("search");
    if (!detailLines[0]) return;
    document.addEventListener("mouseover", function(e) {
      if (e.target.classList && e.target.classList.contains("bar")) {
        if (!pinnedBar) setDetailsForBar(e.target);
      }
    });
    document.addEventListener("mouseout", function(e) {
      if (e.target.classList && e.target.classList.contains("bar") && !searching && !pinnedBar)
        clearDetails();
    });
    document.addEventListener("click", function(e) {
      if (e.target.id === "search") { searchPrompt(); return; }
      if (e.target.classList && e.target.classList.contains("bar")) {
        var bars = document.querySelectorAll(".bar.pinned");
        for (var i = 0; i < bars.length; i++) bars[i].classList.remove("pinned");
        if (pinnedBar === e.target) {
          pinnedBar = null;
          clearDetails();
        } else {
          pinnedBar = e.target;
          pinnedBar.classList.add("pinned");
          setDetailsForBar(pinnedBar);
        }
        return;
      }
      if (pinnedBar) {
        pinnedBar.classList.remove("pinned");
        pinnedBar = null;
        clearDetails();
      }
    });
    document.addEventListener("keydown", function(e) {
      if (e.ctrlKey && e.key === "f") { e.preventDefault(); searchPrompt(); }
    });
  }

  // Slice 4 / V4 — unified search: honest match count + next/prev.
  var _searchMatches = [];
  var _searchIdx = 0;

  function _clearSearchStyles() {
    var bars = document.querySelectorAll(".bar");
    for (var i = 0; i < bars.length; i++) {
      bars[i].style.opacity = "";
      bars[i].style.stroke = "";
      bars[i].style.strokeWidth = "";
    }
  }

  function _focusMatch(idx) {
    if (!_searchMatches.length) return;
    var n = _searchMatches.length;
    _searchIdx = ((idx % n) + n) % n;
    for (var i = 0; i < n; i++) {
      var active = (i === _searchIdx);
      _searchMatches[i].style.stroke = active ? "rgb(230,0,230)" : "rgb(210,140,210)";
      _searchMatches[i].style.strokeWidth = active ? "3" : "1.5";
    }
    try {
      _searchMatches[_searchIdx].scrollIntoView({block: "center", behavior: "smooth"});
    } catch (e) {}
    setDetailsText([
      "Match " + (_searchIdx + 1) + "/" + n + "  ·  n=next, N=prev, Esc=clear"
    ]);
  }

  function _clearSearch() {
    _clearSearchStyles();
    _searchMatches = [];
    searchBtn.textContent = "Search";
    if (!pinnedBar) clearDetails();
    searching = false;
  }

  function searchPrompt() {
    if (searchBtn.textContent === "Reset Search") { _clearSearch(); return; }
    var term = prompt("Search (regex):");
    if (term == null) return;
    var re;
    try { re = new RegExp(term, "i"); } catch (err) { alert("Invalid regex"); return; }
    var bars = document.querySelectorAll(".bar");
    _searchMatches = [];
    for (var i = 0; i < bars.length; i++) {
      var label = bars[i].getAttribute("data-label") || "";
      if (re.test(label)) {
        bars[i].style.opacity = "1";
        _searchMatches.push(bars[i]);
      } else {
        bars[i].style.opacity = "0.3";
        bars[i].style.stroke = "";
        bars[i].style.strokeWidth = "";
      }
    }
    searchBtn.textContent = "Reset Search";
    searching = true;
    if (!_searchMatches.length) {
      setDetailsText([
        "0 matches for " + term + "  ·  Click ‘Reset Search’ to clear"
      ]);
      return;
    }
    _focusMatch(0);
  }

  function _searchNext(delta) {
    if (!_searchMatches.length) return;
    _focusMatch(_searchIdx + delta);
  }

  document.addEventListener("keydown", function(e) {
    if (e.target && (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA")) return;
    if (e.key === "n" && _searchMatches.length) { _searchNext(1); e.preventDefault(); }
    else if (e.key === "N" && _searchMatches.length) { _searchNext(-1); e.preventDefault(); }
    else if (e.key === "Escape" && _searchMatches.length) { _clearSearch(); e.preventDefault(); }
    else if (e.key === "/") { e.preventDefault(); searchPrompt(); }
  });

  window.init = init;
})();
